python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
wb=load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']
print('Search for year-like headers 2020-2024 in Data sheet:')
for r in range(1, ws.max_row+1):
    hits=[]
    for c in range(1, ws.max_column+1):
        if ws.cell(r,c).value in (2020,2021,2022,2023,2024,'2020','2021','2022','2023','2024'):
            hits.append(f'{get_column_letter(c)}{r}={ws.cell(r,c).value!r}')
    if hits:
        print(f'Row {r}: ' + '; '.join(hits))
print('Data non-empty rows 1-20:')
for r in range(1,21):
    entries=[f'{get_column_letter(c)}{r}={ws.cell(r,c).value!r}' for c in range(1,ws.max_column+1) if ws.cell(r,c).value is not None]
    if entries:
        print('; '.join(entries))
